/* No frontend build step: the visual workspace uses the existing FastAPI service. */
(() => {
  'use strict';
  const $ = id => document.getElementById(id), esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const C = '/consolidation/api', W = '/workspace/api';
  function scopedHtml(markup, prefix) {
    const template=document.createElement('template');template.innerHTML=markup;
    const ids=new Set();template.content.querySelectorAll('[id]').forEach(el=>{ids.add(el.id);el.id=prefix+el.id;});
    template.content.querySelectorAll('a[href^="#"]').forEach(el=>{const id=el.getAttribute('href').slice(1);if(ids.has(id))el.setAttribute('href','#'+prefix+id);});
    return template.innerHTML;
  }

  const icons = {
    scale:'M12 3v18M5 21h14M4 7h16M5 7l-4 8h8L5 7zm14 0l-4 8h8l-4-8z',
    home:'M3 10l9-7 9 7v11h-6v-7H9v7H3z', book:'M12 5C8 2 3 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-2-1-6-2-10 1zm0 0v16',
    file:'M14 2H5v20h14V7zm0 0v6h5M8 12h8M8 16h8', plus:'M12 5v14M5 12h14',
    arrow:'M20 12H4m6-6l-6 6 6 6', search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14zm5-2l6 6',
    clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zm0 4v6l4 2', check:'M4 12l5 5L20 6',
    download:'M12 3v12m-5-5l5 5 5-5M4 17v4h16v-4', upload:'M12 17V3m-5 5l5-5 5 5M4 17v4h16v-4',
    edit:'M15 4l5 5M3 21l2-7L17 2l5 5L10 19z', code:'M8 6l-6 6 6 6m8-12l6 6-6 6m-3-16l-2 20',
    print:'M6 8V2h12v6M6 17H2V8h20v9h-4M6 14h12v8H6z', link:'M9 15l6-6M8 17l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2-1l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',
    expand:'M3 9V3h6m6 0h6v6M3 15v6h6m6 0h6v-6', grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z', list:'M3 5h18M3 12h18M3 19h18', flag:'M5 22V3l14 2-4 5 4 5-14-2'
  };
  const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.file}" stroke-linejoin="round" stroke-linecap="round"/></svg>`;
  const btn = (label, action, attrs='', cls='') => `<button type="button" data-action="${action}" ${attrs} class="${cls}">${label}</button>`;
  const link = (label, href, cls='button', name='') => `<a class="${cls}" href="${esc(href)}" ${name?'aria-label="'+esc(name)+'" title="'+esc(name)+'"':''} data-nav>${label}</a>`;
  const pill = (label, cls='') => `<span class="pill ${cls}">${esc(label)}</span>`;
  const empty = message => `<div class="empty">${icon('book')}<p>${esc(message)}</p></div>`;
  const typeOf = op => /omit/.test(op.action) ? 'deleted' : /insert|schedule_add|table_insert/.test(op.action) ? 'inserted' : 'substituted';
  const statusOf = e => e.invalidated_at ? 'stale' : e.approved_at ? 'approved' : 'draft';
  const actions = content => `<div class="actions">${content}</div>`;
  const option = (value, text, selected=false) => `<option value="${esc(value)}" ${selected?'selected':''}>${esc(text)}</option>`;
  let state={}, dirty=false, busy=false, epoch=0, catalog, noticeTimer;
  const actor = () => ($('actor')?.value || localStorage.getItem('nyaya-reviewer') || '').trim();
  const reason = () => ($('reason')?.value || '').trim();
  function auth() { const a=actor(), r=reason(); if(!a || !r) throw Error('Enter your reviewer name and reason before saving.'); localStorage.setItem('nyaya-reviewer',a); return {actor:a, reason:r}; }
  function message(text, error=false) {clearTimeout(noticeTimer);$('notice').textContent=text;$('notice').className=error?'error':'';$('notice').hidden=false;noticeTimer=setTimeout(()=>{$('notice').hidden=true;},error?16000:7000);}
  async function request(url, body, method) {
    const response=await fetch(url,{method:method || (body?'POST':'GET'),headers:body && !(body instanceof FormData)?{'Content-Type':'application/json'}:{},body:body?(body instanceof FormData?body:JSON.stringify(body)):undefined});
    const value=response.headers.get('content-type')?.includes('json')?await response.json():await response.text();
    if(!response.ok) throw Error(typeof value.detail==='string'?value.detail:JSON.stringify(value.detail || value));
    return value;
  }
  async function task(fn){if(busy)return;busy=true;document.body.setAttribute('aria-busy','true');try{await fn();}catch(e){message(e.message,true);}finally{busy=false;document.body.removeAttribute('aria-busy');}}
  function setDirty(){dirty=true;if($('dirty'))$('dirty').textContent='Unsaved review';}
  function clean(){dirty=false;if($('dirty'))$('dirty').textContent='Saved';}
  function modal(title,content){$('modal-title').textContent=title;$('modal-body').innerHTML=content;if(!$('modal').open)$('modal').showModal();}
  function pdf(sourceId, page=1, related=false){const url=related?`${W}/related/${sourceId}/pdf`:`${C}/sources/${sourceId}/pdf`;$('gazette-frame').src=`${url}#page=${page}`;$('gazette-link').href=url;if(!$('gazette').open)$('gazette').showModal();}
  function reviewers(){return `<div class="reviewer"><label>Reviewer<input id="actor" value="${esc(localStorage.getItem('nyaya-reviewer') || '')}" placeholder="Your name" autocomplete="name"></label><label>Reason<input id="reason" placeholder="Reason for this action"></label></div>`;}
  function toolsMenu(){return `<details class="utility-menu"><summary>More <span aria-hidden="true">▾</span></summary><nav aria-label="Other tools"><a href="/viewer">XML viewer and base review</a><a href="/consolidation">Consolidation desk</a></nav></details>`;}
  function admin(title,content,tools='',review=false){$('app').innerHTML=`<nav class="rail" aria-label="Main navigation">${link(icon('scale'),'/admin','','NyayaBandhu workspace')}${link(icon('home'),'/admin','active','Acts dashboard')}${link(icon('book'),'/library','','Legislation library')}</nav><div class="admin-shell"><header class="topbar"><div class="breadcrumb">${title==='Acts'?'':link(icon('arrow'),'/admin','','Back to Acts')}<strong>${esc(title)}</strong></div>${actions(tools+toolsMenu())}</header>${review?reviewers():''}<main id="content">${content}</main></div>`;}

  function publicShell(content){$('app').innerHTML=`<header class="public-header">${link(icon('scale')+'nyayabandhu','/library','brand')}${actions(link('Browse Acts','/library/search','')+link('Review workspace','/admin','button'))}</header><main id="content" class="public-content">${content}</main><footer class="public-footer">NyayaBandhu · Legislation repository <span>· <a href="/docs">API documentation</a></span></footer>`;}
  function navigate(path){if(dirty && !confirm('You have unsaved changes. Leave this page?'))return;clean();history.pushState({},'',path);render();}
  window.addEventListener('popstate',()=>{clean();render();});
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
  document.addEventListener('click',e=>{const a=e.target.closest('a[data-nav]');if(a && !e.ctrlKey&&!e.metaKey){e.preventDefault();navigate(a.getAttribute('href'));}});
  async function render(){const n=++epoch;state.observer?.disconnect();state={};$('app').innerHTML='<div class="loading"><span class="spinner"></span><p>Loading legislative workspace…</p></div>';try{
    const p=location.pathname.split('/').filter(Boolean);
    if(p[0]==='admin'){
      if(p.length===1){await dashboard(n);return;}
      const view=await request(`${W}/works/${p[2]}`);if(n!==epoch)return;state.view=view;
      if(p[3]==='amendments'){await workbench(p[4],n);return;}
      if(p[3]==='edit'){await visual(p[4],n);return;}
      actOverview();return;
    }
    if(p[1]==='search'){await searchPage(n);return;}
    if(p[1]==='acts'){await reader(p[2],n);return;}
    await landing(n);

  }catch(e){if(n===epoch){publicShell(`<div class="card">${empty(e.message)}${link('Open review workspace','/admin')}</div>`);message(e.message,true);}}}

  async function landing(n){
    const works=await request(`${W}/works?public=true`);if(n!==epoch)return;
    const recent=[...works].sort((a,b)=>(b.latest?.approved_at||'').localeCompare(a.latest?.approved_at||'')).slice(0,5);
    publicShell(`<section class="hero"><p class="eyebrow">LEGISLATION LIBRARY</p><h1>Find an Act</h1><p>Read approved text, view earlier versions and check the source gazettes.</p><form id="landing-search-form" role="search"><label class="visually-hidden" for="landing-search">Search Acts</label><input id="landing-search" type="search" placeholder="Search by Act title" autocomplete="off"><button class="blue" type="submit">${icon('search')} Search</button></form></section><section class="recent-acts"><div class="between"><h2>Recently reviewed</h2>${link('View all Acts →','/library/search','text-link')}</div>${recent.length?recent.map(w=>`<article class="recent-row"><div>${link(esc(w.title),`/library/acts/${w.id}`,'act-name')}<p class="muted">${esc(w.jurisdiction.toUpperCase())} · ${esc(w.year)} · Effective ${esc(w.last_updated)}</p></div>${pill(w.approved_count+' '+(w.approved_count===1?'version':'versions'))}</article>`).join(''):empty('No approved Acts are available yet.')}</section>`);
    $('landing-search-form').onsubmit=e=>{e.preventDefault();navigate('/library/search?q='+encodeURIComponent($('landing-search').value.trim()));};
  }

  async function dashboard(n){const works=await request(`${W}/works`);if(n!==epoch)return;state.works=works;state.grid=false;
    admin('Acts',`<div class="content"><div class="between"><div><h1>Acts</h1><p class="muted">Review legislation and manage dated versions.</p></div>${pill(`${works.length} ${works.length===1?'Act':'Acts'}`)}</div><div class="controls"><input class="search" id="act-search" placeholder="Search Acts" aria-label="Search acts"><select id="year-filter" aria-label="Filter by year"><option value="">All years</option>${[...new Set(works.map(w=>w.year))].sort().map(y=>option(y,y)).join('')}</select>${btn('↑↓ Name A–Z','sort')}<div class="segmented">${btn(icon('list'),'view-list','aria-label="Table view"','active')}${btn(icon('grid'),'view-grid','aria-label="Grid view"')}</div></div><div id="acts-result"></div></div>`,btn(icon('plus')+'Add Act','import-base'));
    drawActs();$('act-search').oninput=drawActs;$('year-filter').onchange=drawActs;
  }
  function drawActs(){const query=$('act-search').value.toLowerCase(),year=$('year-filter').value;const rows=state.works.filter(w=>(w.title+' '+w.uri).toLowerCase().includes(query)&&(!year||w.year===year)).sort((a,b)=>a.title.localeCompare(b.title)*(state.desc?-1:1));
    $('acts-result').innerHTML=!rows.length?`<div class="card">${empty(state.works.length?'No Acts match your search.':'No Acts added yet.')}${btn('Add Act','import-base')}</div>`:state.grid?`<div class="act-grid">${rows.map(w=>`<article class="card"><p class="eyebrow">${esc(w.jurisdiction)} · ${esc(w.year)}</p><h2>${esc(w.title)}</h2><p class="muted">${w.amendment_count} ${w.amendment_count===1?'amendment':'amendments'} · ${w.approved_count} approved ${w.approved_count===1?'version':'versions'}</p>${link('Open Act →',`/admin/acts/${w.id}`)}</article>`).join('')}</div>`:`<div class="card table-card"><table><thead><tr><th>Act name</th><th>Year</th><th>Latest approved date</th><th>Amendments</th><th>Actions</th></tr></thead><tbody>${rows.map(w=>`<tr><td>${link(esc(w.title),`/admin/acts/${w.id}`,'act-name')}<span class="muted">${esc(w.jurisdiction.toUpperCase())}</span></td><td>${w.year}</td><td>${w.last_updated||'Awaiting review'}</td><td>${w.amendment_count}</td><td>${link(icon('file')+' Open Act',`/admin/acts/${w.id}`)}</td></tr>`).join('')}</tbody></table></div>`;
  }
  function actOverview(){const v=state.view,s=v.summary;state.tab=state.tab||new URLSearchParams(location.search).get('tab')||'timeline';
    admin(s.title,`<div class="content"><section class="card intro-card"><p class="eyebrow">${esc(s.jurisdiction)} · Principal Act ${s.year}</p><h1>${esc(s.title)}</h1><div class="metrics"><div><strong>${s.amendment_count}</strong><span>Amending instruments</span></div><div><strong>${s.version_count}</strong><span>Saved versions</span></div><div><strong>${s.last_updated||'—'}</strong><span>Latest approved effective date</span></div></div></section><nav class="tabs" aria-label="Act views">${['timeline','versions','issues'].map(t=>btn(t==='timeline'?'Amendment timeline':t==='versions'?'Versions & visual editor':`Reader issues (${v.issues.length})`,'act-tab',`data-tab="${t}"`,state.tab===t?'active':'')).join('')}</nav><div id="act-panel"></div></div>`,btn(icon('upload')+' Upload amendment','import-amendment')+link(icon('book')+' Reader',`/library/acts/${s.id}`),true);
    drawActPanel();
  }
  function relatedPanel(v,edit=false){return `<section class="card"><div class="between"><h2>${icon('book')} Related documents</h2>${edit?btn('+ Add','add-related'):''}</div>${v.related.length?v.related.map(r=>`<div class="related-item"><div class="between"><strong>${esc(r.category)}</strong>${btn('View','related-pdf',`data-id="${r.id}"`)}</div><p>${esc(r.title)}</p><span class="muted">${esc(r.kind)} · ${r.document_date}</span></div>`).join(''):empty('No related documents have been linked to this Act.')}</section>`;}
  function drawActPanel(){const v=state.view;
    if(state.tab==='issues'){$('act-panel').innerHTML=`<div class="card"><h2>Reported issues</h2>${v.issues.length?v.issues.map(x=>`<div class="related-item"><p>${esc(x.message)}</p><span class="muted">#${x.id} · ${esc(x.created)} · version ${esc(x.expression_id)}</span></div>`).join(''):empty('No issues reported.')}</div>`;return;}
    if(state.tab==='versions'){$('act-panel').innerHTML=`<div class="card"><h2>Dated versions</h2><p class="muted">Editing creates a draft version. Approval records the reviewed text and its source evidence.</p><table><thead><tr><th>Effective date</th><th>Version</th><th>Status</th><th>Actions</th></tr></thead><tbody>${v.expressions.map(e=>`<tr><td>${e.effective_date}</td><td>${e.kind==='base'?'Base Act':e.kind==='editorial_correction'?'Editorial correction':'Consolidated Act'}<br><small class="muted">${e.editorial?'Visual / editorial revision · ':''}${e.change_count} changes · ${e.applied_count} instructions</small></td><td>${pill(statusOf(e),statusOf(e))}</td><td>${actions(btn('Read','read-version',`data-id="${e.id}"`)+(e.invalidated_at?'':(e.kind==='consolidated'&&!e.approved_at?'':link(icon('edit')+' Visual edit',`/admin/acts/${v.work.id}/edit/${e.id}`))+(e.approved_at?`<a class="button" href="${C}/expressions/${e.id}/export">Export evidence</a>`:btn('Inspect & approve','approve',`data-id="${e.id}"`)))+btn('XML','xml',`data-id="${e.id}"`))}</td></tr>`).join('')}</tbody></table><details><summary>Audit history</summary>${v.events.map(x=>`<p class="muted">${esc(x.created)} · ${esc(x.actor)} · ${esc(x.kind)} — ${esc(x.reason)}</p>`).join('')}</details></div>`;return;}
    const amendments=v.sources.filter(s=>s.kind==='amendment'),base=v.sources.find(s=>s.kind==='base');
    $('act-panel').innerHTML=`<div class="two-columns"><section class="card"><h2>Amendment timeline ${pill(amendments.length+' instruments')}</h2><ol class="timeline">${amendments.map(s=>{const m=v.manifests.find(m=>m.source_id===s.id),done=m&&v.expressions.some(e=>e.approved_at&&!e.invalidated_at&&e.kind==='consolidated'&&e.effective_date>=(m.body.effective_date||'9999'));return `<li class="${done?'done':''}"><h3>${esc(s.title)}</h3>${pill(m?.body.effective_date||'Date needs review')} ${pill(m?.body.status||'Not extracted',m?.body.status==='ready'?'accepted':'pending')}<p class="muted">Gazette published ${s.date}</p>${actions(btn(icon('file')+' Amendment file','source-pdf',`data-id="${s.id}"`)+(m?link('View changes →',`/admin/acts/${v.work.id}/amendments/${m.id}`):btn('Process amendment','extract',`data-id="${s.id}"`)))}</li>`;}).join('')}<li class="done"><h3>Original base Act</h3><p class="muted">As published · ${base.date}</p>${actions(btn('Gazette PDF','source-pdf',`data-id="${base.id}"`)+btn('Open versions & editor','act-tab','data-tab="versions"'))}</li></ol></section><div>${relatedPanel(v,true)}</div></div>`;
  }
  async function importDialog(kind){catalog=catalog||await request(`${C}/catalog`);state.importKind=kind;const a=actor(),r=reason();modal(kind==='base'?'Add a base Act':'Upload an amendment',`<p class="muted">Choose matching source documents. A PDF upload can be converted here if generated XML is not supplied.</p><div class="form-grid"><label>Reviewer<input id="import-actor" value="${esc(a)}" placeholder="Your name"></label><label>Reason<input id="import-reason" value="${esc(r)}" placeholder="Source import and review"></label><label class="wide">Generated XML<select id="import-xml">${(kind==='base'?catalog.base_xml:catalog.amendment_xml).map(x=>option(x,x)).join('')}</select></label><label class="wide">Matching gazette PDF<select id="import-pdf">${catalog.pdf.map(x=>option(x,x)).join('')}</select></label></div><details style="margin-top:20px"><summary>Upload new source files instead</summary><div class="form-grid"><label>Gazette PDF<input id="upload-pdf" type="file" accept="application/pdf,.pdf"></label><label>Generated XML (optional)<input id="upload-xml" type="file" accept=".xml,application/xml"></label></div><p class="muted">PDF-only conversion needs extractable English text. Scanned PDFs require OCR first.</p></details>${actions(btn('Import source','import-submit','','primary'))}`);const matchPdf=()=>{const stem=$('import-xml').value.split('/').pop()?.replace(/\.xml$/,'');const match=catalog.pdf.find(p=>p.split('/').pop()===stem+'.pdf');if(match)$('import-pdf').value=match;};$('import-xml').onchange=matchPdf;matchPdf();}
  async function submitImport(){const identity={actor:$('import-actor').value.trim(),reason:$('import-reason').value.trim()};if(!identity.actor||!identity.reason)throw Error('Enter a reviewer name and reason.');localStorage.setItem('nyaya-reviewer',identity.actor);const shared={kind:state.importKind,...identity};if(shared.kind==='amendment'){shared.work_id=state.view.work.id;shared.revision=state.view.work.revision;}
    let result;if($('upload-pdf').files.length){const form=new FormData();Object.entries(shared).forEach(([k,v])=>form.append(k,v));form.append('pdf',$('upload-pdf').files[0]);if($('upload-xml').files.length)form.append('xml',$('upload-xml').files[0]);message('Processing the gazette…');result=await request(`${W}/upload`,form);}else result=await request(`${C}/sources`,{...shared,xml_path:$('import-xml').value,pdf_path:$('import-pdf').value});
    $('modal').close();clean();navigate(`/admin/acts/${result.work_id}${state.importKind==='base'?'?tab=versions':''}`);message('Source imported. Review the base or process the amendment.');
  }

  async function workbench(mid,n){const v=state.view,m=v.manifests.find(x=>x.id===mid);if(!m)throw Error('Amendment instructions not found');state.manifest=m;state.body=structuredClone(m.body);state.filter='all';state.rows=[];
    const candidates=v.expressions.filter(e=>e.approved_at&&!e.invalidated_at&&(!m.body.effective_date||e.effective_date<=m.body.effective_date));
    // An already applied instrument should be inspected against its own predecessor.
    let parent=null;for(const e of candidates){if(e.kind==='consolidated'&&e.effective_date===m.body.effective_date){parent=v.expressions.find(x=>x.id===e.parent_id);break;}}
    parent=parent||candidates.at(-1);state.parent=parent?.id||'';
    admin('Amendment review',`<div class="workbench-controls"><div class="between"><div class="filters">${btn('All','filter','data-filter="all"','active')}${['inserted','substituted','deleted'].map(x=>btn(x[0].toUpperCase()+x.slice(1),'filter',`data-filter="${x}"`,x)).join('')}</div>${actions(btn('↑ Previous','previous')+btn('↓ Next','next')+'<select id="jump" aria-label="Jump to affected provision"><option>Choose a change…</option></select>')}</div></div><details class="decision-panel" open><summary>${esc(v.sources.find(x=>x.id===m.source_id)?.title || 'Amendment')} · Instrument decisions</summary><div class="form-grid"><label>Approved predecessor<select id="parent">${candidates.map(e=>option(e.id,`${e.effective_date} · ${e.kind}`,e.id===state.parent)).join('')}</select></label><label>Effective date<input type="date" id="effective-date" value="${esc(m.body.effective_date||'')}"></label><label>Instrument order<input id="sequence" type="number" min="1" value="${m.body.sequence}"></label><label class="check"><input type="checkbox" id="identity" ${m.body.identity_confirmed?'checked':''}> Principal Act identity confirmed</label><label class="wide">Commencement evidence<textarea id="date-evidence" rows="2">${esc(m.body.date_evidence||'')}</textarea></label><label class="check"><input type="checkbox" id="date-confirmed" ${m.body.date_confirmed?'checked':''}> Commencement date reviewed</label><span class="muted">Saving a changed review makes its dependent versions stale.</span></div></details><div class="diff-columns-heading"><div>Original document · predecessor</div><div>Amended document · proposed wording</div></div><div class="diff-list" id="diff-list"><div class="loading"><span class="spinner"></span><p>The amendment document is being processed…</p></div></div><div class="batch-bar"><div><span id="review-progress"></span> · <span id="dirty" class="dirty-label">Saved</span><div class="reading-badge" id="viewing">Viewing changes by provision</div></div>${actions(btn('Save review','save-review')+btn('Validate complete batch','preview-batch','','primary'))}</div>`,link(icon('arrow')+' Act overview',`/admin/acts/${v.work.id}`)+btn(icon('print'),'print','aria-label="Print comparison"')+btn(icon('link'),'share','aria-label="Copy link"')+btn(icon('expand'),'expand','aria-label="Expand workspace"'),true);
    ['effective-date','sequence','identity','date-evidence','date-confirmed'].forEach(id=>$(id).addEventListener('change',()=>{readDecisions();setDirty();}));
    $('parent').onchange=()=>task(async()=>{state.parent=$('parent').value;await refreshCanvas();});$('jump').onchange=()=>jump($('jump').value);
    if(!state.parent){$('diff-list').innerHTML=empty('Approve a base version before reviewing amendment targets.');return;}
    await refreshCanvas(n);
  }
  function readDecisions(){Object.assign(state.body,{effective_date:$('effective-date').value||null,sequence:Number($('sequence').value),identity_confirmed:$('identity').checked,date_confirmed:$('date-confirmed').checked,date_evidence:$('date-evidence').value});}
  async function refreshCanvas(n=epoch){readDecisions();const result=await request(`${W}/manifests/${state.manifest.id}/canvas`,{expression_id:state.parent,manifest_revision:state.manifest.revision,body:state.body});if(n!==epoch)return;state.rows=result.rows;state.provisions=result.provisions;drawChanges();}
  function drawChanges(){const rows=state.rows.filter(r=>state.filter==='all'||typeOf(r)===state.filter);$('diff-list').innerHTML=rows.length?rows.map(r=>{const op=state.body.operations.find(o=>o.id===r.id),status=op.review_decision||op.review_status,t=typeOf(op),source=op.source;return `<article class="diff-row" id="change-${esc(r.id)}" data-id="${esc(r.id)}" data-type="${t}" data-status="${status}"><div class="diff-cell"><div class="diff-title">${pill('Original')}<strong>${esc(r.label||op.id)}</strong></div>${r.before_html?scopedHtml(r.before_html,'before-'+r.id+'-'):'<p class="muted">'+(r.effect?'Separate legal effect; no principal-Act text change.':'No target could be rendered.')+'</p>'}${r.before_diff?`<details><summary>Exact wording difference</summary><div class="diff-prose">${r.before_diff}</div></details>`:''}</div><div class="diff-cell proposed"><div class="diff-title">${pill(r.effect?'Legal effect':t,t)}${pill(status,status)}<strong>${esc(r.label||op.id)}</strong></div>${r.conflict?`<div class="conflict">${esc(r.conflict)}</div>`:r.after_html?scopedHtml(r.after_html,'after-'+r.id+'-'):`<p>${esc(op.classification||'The provision is omitted.')}</p>`}${r.after_diff?`<details><summary>Exact wording difference</summary><div class="diff-prose">${r.after_diff}</div></details>`:''}<details><summary>Gazette instruction</summary><blockquote class="source-quote">${esc(source.quote)}</blockquote></details>${actions(btn('View amendment','source-pdf',`data-id="${state.manifest.source_id}" data-page="${source.pdf_pages?.[0]||1}"`)+btn('Edit proposal','edit-operation',`data-id="${op.id}"`)+btn(status==='accepted'?'✓ Accepted':'Accept','accept-operation',`data-id="${op.id}" ${r.conflict?'disabled':''}`,'accept')+btn('Reject','reject-operation',`data-id="${op.id}"`,'reject'))}<p class="source-note">${status==='accepted'?'Accepted review · ':''}Source: ${esc(source.source_eid)} · Gazette page ${esc((source.pdf_pages||[]).join(', '))}${op.review_note?'<br>'+esc(op.review_note):''}</p></div></article>`;}).join(''):empty('No changes of this kind.');
    $('jump').innerHTML=rows.map(r=>option(r.id,`${r.label||r.id} · ${r.action}`)).join('');const count=state.body.operations.filter(o=>o.review_status==='accepted').length;$('review-progress').textContent=`${count} / ${state.body.operations.length} accepted`;
    state.observer?.disconnect();state.observer=new IntersectionObserver(entries=>{const first=entries.find(e=>e.isIntersecting);if(first){state.visible=first.target.dataset.id;$('viewing').textContent='Viewing: '+(state.rows.find(r=>r.id===state.visible)?.label||state.visible);}}, {rootMargin:'-130px 0px -50% 0px'});document.querySelectorAll('.diff-row').forEach(el=>state.observer.observe(el));
  }
  function jump(id){document.getElementById('change-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});state.visible=id;}
  async function saveReview(){if(!dirty){message('No unsaved review changes.');return;}readDecisions();const result=await request(`${C}/manifests/${state.manifest.id}/review`,{...auth(),revision:state.view.work.revision,manifest_revision:state.manifest.revision,body:state.body});state.manifest=result.manifest;state.body=structuredClone(result.manifest.body);state.view.work.revision=result.revision;clean();message(result.stale?.length?'Review saved; dependent versions are now stale.':'Review revision saved.');}
  function tableForm(rows,path){return `<div class="table-edit"><table><tbody>${rows.map((row,i)=>`<tr>${row.map((cell,j)=>`<td><textarea aria-label="Row ${i+1}, column ${j+1}" data-table-path="${path}" data-row="${i}" data-col="${j}">${esc(cell)}</textarea></td>`).join('')}<td>${btn('×','remove-proposal-row',`data-path="${path}" data-row="${i}" aria-label="Remove row ${i+1}"`)}</td></tr>`).join('')}</tbody></table>${btn('+ Row','add-proposal-row',`data-path="${path}"`)}</div>`;}
  function fragmentForm(spec,path){return `<div class="fragment" data-path="${path}"><div class="form-grid"><label>Provision type<select data-fragment="tag" data-path="${path}">${['section','subsection','clause','subclause','proviso','hcontainer'].map(t=>option(t,t,t===spec.tag)).join('')}</select></label><label>Printed number<input data-fragment="num" data-path="${path}" value="${esc(spec.num||'')}"></label><label class="wide">Heading<input data-fragment="heading" data-path="${path}" value="${esc(spec.heading||'')}"></label><label class="wide">Legal wording<textarea data-fragment="text" data-path="${path}">${esc(spec.text||'')}</textarea></label></div>${(spec.children||[]).map((c,i)=>fragmentForm(c,path+'.children.'+i)).join('')}${spec.table?tableForm(spec.table,path+'.table'):''}${btn('+ Child provision','add-proposal-child',`data-path="${path}"`)}</div>`;}
  function operationModal(id,draft){state.editId=id;const op=draft||state.body.operations.find(x=>x.id===id);state.editOp=structuredClone(op);
    modal('Review proposed wording',`<div class="source-quote">${esc(op.source.quote)}</div><div class="form-grid"><label>Action<select id="op-action">${['text_replace','text_insert','text_omit','insert_provision','replace_provision','omit_provision','renumber','schedule_add','table_insert','effect','blocked','slot_edits'].map(a=>option(a,a.replaceAll('_',' '),a===op.action)).join('')}</select></label><label>Position<select id="op-position">${['after','before','last_child'].map(x=>option(x,x,x===op.position)).join('')}</select></label><label class="wide">Target provision<select id="op-target-choice"><option value="keep">Keep extracted target: ${esc(op.target?.eid || op.target?.region || (op.target?.path||[]).map(x=>x.join(' ')).join(' / ') || 'Separate legal effect')}</option>${['longTitle','preamble','act'].map(r=>option('region:'+r,r==='longTitle'?'Long title':r==='act'?'Whole Act':'Preamble')).join('')}${(state.provisions||[]).map(p=>option('eid:'+p.eid,p.label+' · '+p.eid)).join('')}</select></label><details class="wide"><summary>Advanced target selector</summary><textarea id="op-target" rows="2" aria-label="Advanced target selector">${esc(JSON.stringify(op.target||{},null,2))}</textarea></details><label>Exact words / anchor<textarea id="op-old">${esc(op.old||'')}</textarea></label><label>Replacement or inserted words<textarea id="op-new">${esc(op.new||'')}</textarea></label><label>Expected match count<input id="op-count" type="number" min="1" value="${op.count||1}"></label><label>New number<input id="op-number" value="${esc(op.new_number||'')}"></label><label class="check"><input id="op-global" type="checkbox" ${op.global?'checked':''}> Across the whole Act</label><label class="check"><input id="op-word" type="checkbox" ${op.whole_word?'checked':''}> Whole words only</label><label class="check"><input id="op-protected" type="checkbox" ${op.allow_protected?'checked':''}> Protected inline text reviewed</label><label>Separate effect classification<input id="op-effect" value="${esc(op.classification||'')}"></label></div>${op.fragment?fragmentForm(op.fragment,'fragment'):''}${(op.fragments||[]).map((f,i)=>fragmentForm(f,'fragments.'+i)).join('')}${op.rows?`${tableForm(op.rows,'rows')}<label>After group<input id="op-group" value="${esc(op.after_group||'')}"></label>`:''}${btn('+ Provision wording','add-proposal-provision')}<label>Review note<textarea id="op-note">${esc(op.review_note||'')}</textarea></label><details><summary>Reference decisions and advanced operation fields</summary><p class="muted">Use the detailed instruction desk for complex reference reconciliation. Changes to source quotations are not permitted.</p><label>Additional fields (JSON)<textarea id="op-extra">${esc(JSON.stringify(Object.fromEntries(['reference_updates','inline_removals','container_reference_updates','edits'].filter(k=>op[k]).map(k=>[k,op[k]])),null,2))}</textarea></label><a href="/consolidation?work=${state.view.work.id}" target="_blank" rel="noopener">Open instruction desk</a></details><div id="inspection"></div>${actions(btn('Inspect & bind exact matches','inspect-operation')+btn('Keep proposal changes','keep-operation','','primary'))}`);
  }
  function collectOperation(){const op=state.editOp;Object.assign(op,{action:$('op-action').value,target:$('op-target-choice').value==='keep'?JSON.parse($('op-target').value):$('op-target-choice').value.startsWith('eid:')?{eid:$('op-target-choice').value.slice(4)}:{region:$('op-target-choice').value.slice(7)},old:$('op-old').value,new:$('op-new').value,count:Number($('op-count').value),position:$('op-position').value,new_number:$('op-number').value,global:$('op-global').checked,whole_word:$('op-word').checked,allow_protected:$('op-protected').checked,classification:$('op-effect').value,review_note:$('op-note').value});
    document.querySelectorAll('[data-fragment]').forEach(el=>{const path=el.dataset.path.split('.');let node=op;path.forEach(k=>node=node[k]);node[el.dataset.fragment]=el.dataset.fragment==='table'?JSON.parse(el.value):el.value;});document.querySelectorAll('[data-table-path]').forEach(el=>{let rows=op;el.dataset.tablePath.split('.').forEach(k=>rows=rows[k]);rows[Number(el.dataset.row)][Number(el.dataset.col)]=el.value;});if($('op-group'))op.after_group=$('op-group').value;
    const extra=JSON.parse($('op-extra').value||'{}');for(const key of ['reference_updates','inline_removals','container_reference_updates','edits'])delete op[key];for(const k of Object.keys(extra)){if(!['reference_updates','inline_removals','container_reference_updates','edits'].includes(k))throw Error('Unsupported advanced field: '+k);op[k]=extra[k];}return op;
  }
  async function inspectOperation(){const op=collectOperation(),body=structuredClone(state.body);body.operations[body.operations.findIndex(x=>x.id===op.id)]=op;const result=await request(`${C}/manifests/${state.manifest.id}/inspect`,{expression_id:state.parent,operation_id:op.id,body});if(result.target_error)throw Error(result.target_error);op.expected_hash=result.expected_hash;delete op.target_identity;if(result.occurrences)op.occurrences=result.occurrences;
    $('inspection').innerHTML=`<div class="coverage-note">Bound this target and ${result.occurrences?.length||0} exact matches. Check the wording and references below before accepting.</div><p>${esc(result.target_text)}</p><pre>${esc(JSON.stringify({occurrences:result.occurrences,incoming_references:result.incoming_references,inline_candidates:result.inline_candidates},null,2))}</pre>`;
  }
  async function batchPreview(){if(!$('effective-date').value)throw Error('Set and review the effective date first.');if(dirty)await saveReview();const result=await request(`${C}/works/${state.view.work.id}/preview`,{parent_id:state.parent,effective_date:state.body.effective_date});state.preview=result;modal('Validate complete amendment batch',`<p>${result.ok?'The complete batch passes XML, identifier, reference and language validation.':'The batch needs correction before it can be saved.'}</p><pre>${esc(result.validation?.summary||JSON.stringify(result.conflicts,null,2))}</pre>${result.conflicts?.length?`<div class="conflict">${esc(JSON.stringify(result.conflicts))}</div>`:''}<details><summary>Full XML difference</summary><pre>${esc(result.diff||result.xml_diff||'')}</pre></details>${actions(btn('Back to review','close-modal')+btn('Save consolidated draft','apply-batch',result.ok?'':'disabled','primary'))}`);}

  async function visual(eid,n){const v=state.view,expression=v.expressions.find(e=>e.id===eid);if(!expression)throw Error('Version not found');state.expression=expression;const doc=await request(`${W}/expressions/${eid}/document`);if(n!==epoch)return;state.document=doc;state.visualPayload=null;
    admin('Visual Act editor',`<div class="content"><div class="between"><div><p class="eyebrow">${expression.effective_date} · ${statusOf(expression)}</p><h1>${esc(v.summary.title)}</h1></div>${btn('Source gazette','source-pdf',`data-id="${v.summary.base_source_id}"`)}</div><p class="muted">Select a provision, then edit its wording on the page. Shaded inline references and language spans are protected. Save creates a new revision for approval.</p><div class="visual-layout"><aside class="card provision-nav"><label>Find provision<input id="provision-search" placeholder="Number or heading"></label><div id="provision-list"></div></aside><section><div class="visual-comparison"><article class="card"><p class="eyebrow">Original provision</p><div id="visual-before" class="akn-document"></div></article><article class="card"><p class="eyebrow">Draft provision · click to edit</p><div id="visual-after" class="akn-document visual-edit"></div></article></div><div class="editor-tools" id="editor-tools"></div><section class="card"><h3>Evidence for this revision</h3><div class="form-grid"><label>Source<select id="evidence-source">${v.sources.map(s=>option(s.id,s.title)).join('')}</select></label><label>PDF pages<input id="evidence-pages" placeholder="e.g. 10, 11"></label><label class="wide">Source quotation<textarea id="evidence-quote" placeholder="Quote the gazette wording supporting this correction"></textarea></label></div><div id="visual-result"></div>${actions(btn('Preview revision','visual-preview')+btn('Save draft revision','visual-save','','primary'))}</section></section></div></div>`,link('Act versions',`/admin/acts/${v.work.id}`),true);
    function list(){const q=$('provision-search').value.toLowerCase();$('provision-list').innerHTML=doc.outline.filter(p=>(p.label+' '+p.eid).toLowerCase().includes(q)).map(p=>btn(esc(p.label),'select-provision',`data-id="${p.eid}"`,p.eid===state.selected?'active':'')).join('');}state.drawOutline=list;$('provision-search').oninput=list;list();if(doc.outline.length)await selectProvision(doc.outline[0].eid);
  }
  async function selectProvision(eid){const n=epoch;if(dirty && !confirm('Discard unsaved wording before selecting another provision?'))return;clean();const response=await request(`${W}/expressions/${state.expression.id}/provisions/${encodeURIComponent(eid)}`);if(n!==epoch)return;state.selected=eid;state.visual=response;state.visualPayload=null;state.view.work.revision=response.revision;$('visual-before').innerHTML=scopedHtml(response.html,'original-');$('visual-after').innerHTML=scopedHtml(response.html,'draft-');state.drawOutline();
    const dom=$('visual-after'),xmlOwners=dom.querySelectorAll('[data-eid]');state.fields=structuredClone(response.editor.fields||[]);
    state.fields.forEach((field,i)=>{let element;if(field.tag==='p')element=Array.from(dom.querySelectorAll('p.akn-p')).find(x=>x.dataset.eid===field.eid);else {const owner=Array.from(xmlOwners).find(x=>x.dataset.eid===field.eid);element=owner?.querySelector(':scope > .akn-label .akn-heading-text');if(!element){const headings=Array.from(dom.querySelectorAll('.akn-heading-text'));const index=state.fields.slice(0,i).filter(f=>f.tag==='heading').length;element=headings[index];}}
      if(!element)return;element.replaceChildren();field.segments.forEach((segment,j)=>{const span=document.createElement('span');span.contentEditable='plaintext-only';span.dataset.field=i;span.dataset.segment=j;span.textContent=segment;span.setAttribute('aria-label',`Editable ${field.tag} text`);span.oninput=()=>{state.fields[i].segments[j]=span.innerText;state.visualPayload=null;setDirty();};span.onpaste=e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));};element.append(span);if(j<field.protected.length){const chip=document.createElement('span');chip.className='protected';chip.textContent=field.protected[j].replace(/^[^:]+: /,'');chip.title='Protected inline XML';element.append(chip);}});
    });
    $('editor-tools').innerHTML=response.structural?`<select id="visual-action" aria-label="Structure action"><option value="text">Edit wording</option><option value="add">Add provision</option><option value="remove">Remove provision</option><option value="renumber">Renumber</option><option value="move">Move</option></select><select id="child-type" aria-label="Child type">${response.editor.add_types.map(t=>option(t,t)).join('')}</select><input id="new-number" placeholder="New number" aria-label="New number"><select id="move-direction" aria-label="Move direction"><option value="up">Move up</option><option value="down">Move down</option></select>`:'<p class="muted">Edit the wording here; table structure stays fixed. Structural statutory amendments belong in the amendment workbench.</p>';
    ['visual-action','child-type','new-number','move-direction'].forEach(id=>{if($(id))$(id).onchange=setDirty;});
  }
  function visualRequest(preview){const action=$('visual-action')?.value||'text';if(action!=='text'&&JSON.stringify(state.fields)!==JSON.stringify(state.visual.editor.fields))throw Error('Save your wording edits before changing the structure. Each action creates its own revision.');const payload=action==='text'?{action,fields:state.fields}:action==='add'?{action,child_type:$('child-type').value}:action==='renumber'?{action,number:$('new-number').value}:action==='move'?{action,direction:$('move-direction').value}:{action};return {...auth(),revision:state.view.work.revision,xml_hash:state.expression.xml_hash,eid:state.selected,payload,evidence:{source_id:$('evidence-source').value,pdf_pages:$('evidence-pages').value.split(',').map(x=>Number(x.trim())),quote:$('evidence-quote').value},preview};}
  async function saveVisual(preview){const result=await request(`${W}/expressions/${state.expression.id}/visual`,visualRequest(preview));if(preview){$('visual-result').innerHTML=`<div class="coverage-note">Valid revision. Review the result before saving.</div>${scopedHtml(result.after_html,'preview-')}<details><summary>XML changes</summary><pre>${esc(result.diff)}</pre></details>`;message('Preview is valid; save to create a draft.');}else {clean();message('Draft revision saved. Inspect and approve it in Versions.');navigate(`/admin/acts/${state.view.work.id}?tab=versions`);}}

  async function searchPage(n){const works=await request(`${W}/works?public=true`);if(n!==epoch)return;state.works=works;publicShell(`<h1>Browse Acts</h1><p class="muted">Search approved Acts and their earlier versions.</p><div class="controls"><input id="public-search" class="search" aria-label="Search legislation" placeholder="Search by legislation name or title…"><select id="public-year" aria-label="Filter year"><option value="">All years</option>${[...new Set(works.map(w=>w.year))].sort().map(y=>option(y,y)).join('')}</select>${btn(icon('search')+' Search','public-search','','blue')}</div>${works.some(w=>w.recent_activity)?'<p class="coverage-note">'+works.filter(w=>w.recent_activity).length+' recently approved '+(works.filter(w=>w.recent_activity).length===1?'Act':'Acts')+'.</p>':''}<div id="public-results"></div>`);$('public-search').value=new URLSearchParams(location.search).get('q')||'';$('public-search').oninput=drawPublicResults;$('public-year').onchange=drawPublicResults;drawPublicResults();}
  function drawPublicResults(){const q=$('public-search').value.toLowerCase(),year=$('public-year').value;const rows=state.works.filter(w=>w.title.toLowerCase().includes(q)&&(!year||w.year===year));$('public-results').innerHTML=rows.map(w=>`<article class="public-card"><div class="document-icon">${icon('file')}</div><div><h2>${link(esc(w.title),`/library/acts/${w.id}`,'act-name')}</h2><p class="meta">${esc(w.jurisdiction.toUpperCase())} · ${w.year} · Latest effective date ${w.last_updated}</p>${pill(w.approved_count+' approved versions')} ${pill(w.amendment_count+' registered amendments')} ${w.recent_activity?pill('Recent review','approved'):''}</div></article>`).join('')||empty('No Acts match your search.');}
  async function reader(id,n){const v=await request(`${W}/works/${id}?public=true`);if(n!==epoch)return;state.view=v;state.readerTab='current';const selected=new URLSearchParams(location.search).get('version');state.readerVersion=v.expressions.find(e=>e.id===selected)?.id||v.expressions.at(-1).id;
    publicShell(`${link('← All legislations','/library/search','')}<div class="between" style="margin-top:25px"><div><p class="eyebrow">${esc(v.summary.jurisdiction)} · ${v.summary.year} · English</p><h1>${esc(v.summary.title)}</h1></div></div>${actions(btn(icon('code')+' View XML','reader-xml')+btn(icon('download')+' Download PDF','reader-pdf')+btn(icon('flag')+' Report issue','report-issue'))}<nav class="tabs">${['current','related','timeline'].map(t=>btn(t==='current'?'Current version':t==='related'?'Related documents':'Act timeline','reader-tab',`data-tab="${t}"`,t==='current'?'active':'')).join('')}</nav><div class="public-reading"><section class="card" id="reader-panel"></section><aside class="card gazettes"><h2>Gazette documents</h2>${v.sources.map(s=>`<div class="related-item"><strong>${esc(s.title)}</strong><p class="muted">${s.date}</p>${btn('Open gazette ↗','source-pdf',`data-id="${s.id}"`)}</div>`).join('')}</aside></div>`);await drawReader();
  }
  async function drawReader(){const v=state.view;
    if(state.readerTab==='related'){$('reader-panel').innerHTML=relatedPanel(v);return;}
    if(state.readerTab==='timeline'){$('reader-panel').innerHTML=`<h2>Act timeline</h2><ol class="timeline">${v.expressions.map(e=>`<li class="done"><h3>${e.effective_date} · ${e.kind==='base'?'Base Act':e.kind==='editorial_correction'?'Editorial correction':'Consolidated version'}</h3><p class="muted">${e.applied_count} reviewed instructions applied</p>${btn('Read this version','read-public-version',`data-id="${e.id}"`)}</li>`).join('')}${v.related.map(r=>`<li class="done"><h3>${r.document_date} · ${esc(r.title)}</h3><p>${esc(r.kind)}</p></li>`).join('')}</ol>`;return;}
    const requested=state.readerVersion,document=await request(`${W}/expressions/${requested}/document?public=true`);if(state.readerVersion!==requested||state.readerTab!=='current')return;state.document=document;const lookup=await request(`${W}/works/${v.summary.id}/coverage?as_of=${document.effective_date}`);if(state.readerVersion!==requested||state.readerTab!=='current')return;
    $('reader-panel').innerHTML=`<label class="version-select">View version<select id="version-select">${v.expressions.map(e=>option(e.id,`${e.effective_date} · ${e.kind==='base'?'Base Act':e.kind.replaceAll('_',' ')}`,e.id===requested)).join('')}</select></label><label class="reading-outline">Go to provision<select id="reader-jump"><option value="">Choose a provision…</option>${document.outline.map(p=>option(p.eid,p.label)).join('')}</select></label><p class="coverage-note">${lookup.complete_for_registered_sources?'Reviewed against registered amendments for this date.':'Registered amendments remain unresolved for this date.'} This view reflects local approval.</p><article class="akn-document" id="reader-document">${document.html}</article>`;
    $('version-select').onchange=()=>task(async()=>{state.readerVersion=$('version-select').value;history.replaceState({},'',`/library/acts/${v.summary.id}?version=${state.readerVersion}`);await drawReader();});$('reader-jump').onchange=()=>{const id=$('reader-jump').value;Array.from($('reader-document').querySelectorAll('[data-eid]')).find(x=>x.dataset.eid===id)?.scrollIntoView({behavior:'smooth',block:'start'});};
  }

  document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id;task(async()=>{switch(action){
    case 'close-modal':$('modal').close();break;case 'close-gazette':$('gazette').close();$('gazette-frame').src='about:blank';break;
    case 'import-base':await importDialog('base');break;case 'import-amendment':await importDialog('amendment');break;case 'import-submit':await submitImport();break;
    case 'sort':state.desc=!state.desc;button.textContent=state.desc?'↑↓ Name Z–A':'↑↓ Name A–Z';drawActs();break;
    case 'view-grid':case 'view-list':state.grid=action==='view-grid';document.querySelectorAll('.segmented button').forEach(x=>x.classList.toggle('active',x===button));drawActs();break;
    case 'act-tab':{const savedActor=actor(),savedReason=reason();state.tab=button.dataset.tab;history.replaceState({},'',`/admin/acts/${state.view.work.id}?tab=${state.tab}`);actOverview();$('actor').value=savedActor;$('reason').value=savedReason;break;}
    case 'source-pdf':pdf(id,Number(button.dataset.page)||1);break;case 'related-pdf':pdf(id,1,true);break;
    case 'extract':{message('The amendment document is being processed…');const r=await request(`${C}/sources/${id}/extract`,{...auth(),revision:state.view.work.revision});navigate(`/admin/acts/${state.view.work.id}/amendments/${r.manifest.id}`);break;}
    case 'read-version':{const d=await request(`${W}/expressions/${id}/document`);modal('Dated Act · '+d.effective_date,`<div class="akn-document">${d.html}</div>`);break;}
    case 'xml':{const raw=await request(`${C}/expressions/${id}/xml`);modal('Akoma Ntoso XML',`<pre>${esc(raw)}</pre>`);break;}
    case 'approve':{const v=state.view.expressions.find(x=>x.id===id);state.approval=v;const d=await request(`${W}/expressions/${id}/document`);modal('Approve reviewed version',`<p>Approve this exact dated text after comparing it with the gazette. This records your name and reason.</p>${v.supersedes?'<p class="conflict">Approving this correction supersedes its predecessor and makes dependent versions stale. Rebuild those versions from the corrected text.</p>':''}<p class="muted">${esc(v.effective_date)} · XML SHA-256 ${esc(v.xml_hash)}</p><div class="akn-document" style="max-height:40vh;overflow:auto">${d.html}</div>${actions(btn('Approve exact version','confirm-approve','','primary'))}`);break;}
    case 'confirm-approve':{await request(`${C}/expressions/${state.approval.id}/approve`,{...auth(),revision:state.view.work.revision,xml_hash:state.approval.xml_hash});$('modal').close();await render();message('Version approved and available in the reader.');break;}
    case 'add-related':{catalog=catalog||await request(`${C}/catalog`);modal('Link a reviewed subordinate document',`<p class="muted">Record the relationship after checking the source. The PDF will appear beside the approved Act in the reader.</p><div class="form-grid"><label class="wide">Document title<input id="related-title"></label><label>Kind<select id="related-kind">${['Rules','Regulations','Notification'].map(x=>option(x,x)).join('')}</select></label><label>Category<input id="related-category" placeholder="e.g. Education"></label><label>Document date<input id="related-date" type="date"></label><label>Source PDF<select id="related-pdf">${catalog.pdf.map(p=>option(p,p)).join('')}</select></label></div>${actions(btn('Save reviewed relationship','save-related','','primary'))}`);break;}
    case 'save-related':{await request(`${W}/works/${state.view.work.id}/related`,{...auth(),revision:state.view.work.revision,title:$('related-title').value,kind:$('related-kind').value,category:$('related-category').value,document_date:$('related-date').value,pdf_path:$('related-pdf').value});$('modal').close();await render();message('Related document linked.');break;}
    case 'filter':state.filter=button.dataset.filter;document.querySelectorAll('.filters button').forEach(x=>x.classList.toggle('active',x===button));drawChanges();break;
    case 'previous':case 'next':{const rows=state.rows.filter(r=>state.filter==='all'||typeOf(r)===state.filter);let i=rows.findIndex(r=>r.id===state.visible);i=Math.max(0,Math.min(rows.length-1,i+(action==='next'?1:-1)));if(rows[i])jump(rows[i].id);break;}
    case 'accept-operation':{const op=state.body.operations.find(x=>x.id===id);op.review_status='accepted';op.review_decision='accepted';setDirty();drawChanges();break;}
    case 'reject-operation':{const op=state.body.operations.find(x=>x.id===id),note=prompt('Why does this proposal need correction? Rejecting leaves it unresolved and blocks the batch.');if(!note?.trim())break;op.review_status='pending';op.review_decision='rejected';op.review_note=note.trim();setDirty();drawChanges();break;}
    case 'save-review':await saveReview();break;case 'preview-batch':await batchPreview();break;
    case 'apply-batch':{const r=await request(`${C}/works/${state.view.work.id}/apply`,{...auth(),revision:state.view.work.revision,parent_id:state.parent,effective_date:state.body.effective_date,preview_hash:state.preview.preview_hash});$('modal').close();clean();navigate(`/admin/acts/${state.view.work.id}?tab=versions`);message('Consolidated draft saved. Inspect and approve it in Versions.');break;}
    case 'edit-operation':operationModal(id);break;case 'inspect-operation':await inspectOperation();break;
    case 'add-proposal-provision':case 'add-proposal-child':case 'add-proposal-row':case 'remove-proposal-row':{const op=collectOperation();if(action==='add-proposal-provision'){const child={tag:'subsection',num:'',text:''};if(['replace_provision','schedule_add'].includes(op.action))op.fragment=op.fragment||{...child,tag:op.action==='schedule_add'?'hcontainer':'subsection'};else {op.fragments=op.fragments||(op.fragment?[op.fragment]:[]);delete op.fragment;op.fragments.push(child);}}else {let target=op;button.dataset.path.split('.').forEach(k=>target=target[k]);if(action==='add-proposal-child'){target.children=target.children||[];target.children.push({tag:'clause',num:'',text:''});}else if(action==='add-proposal-row'){target.push(Array(target[0]?.length||2).fill(''));}else {if(target.length===1)throw Error('Keep at least one row.');target.splice(Number(button.dataset.row),1);}}operationModal(state.editId,op);break;}
    case 'keep-operation':{const op=collectOperation();op.review_status='pending';delete op.review_decision;state.body.operations[state.body.operations.findIndex(x=>x.id===op.id)]=op;setDirty();$('modal').close();await refreshCanvas();break;}
    case 'select-provision':await selectProvision(id);break;case 'visual-preview':await saveVisual(true);break;case 'visual-save':await saveVisual(false);break;
    case 'public-search':drawPublicResults();break;case 'reader-tab':state.readerTab=button.dataset.tab;document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x===button));await drawReader();break;
    case 'read-public-version':state.readerVersion=id;history.replaceState({},'',`/library/acts/${state.view.summary.id}?version=${id}`);state.readerTab='current';document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab==='current'));await drawReader();break;
    case 'reader-xml':{const raw=await request(`${W}/expressions/${state.readerVersion}/xml`);modal('Akoma Ntoso XML',`<pre>${esc(raw)}</pre>`);break;}
    case 'reader-pdf':location.href=`${W}/expressions/${state.readerVersion}/pdf`;break;
    case 'report-issue':modal('Report an issue in this version',`<p class="muted">Describe the provision and source evidence. Your report will appear in the review workspace.</p><label>Issue<textarea id="issue-message" minlength="10" maxlength="5000"></textarea></label>${actions(btn('Submit issue','submit-issue','','blue'))}`);break;
    case 'submit-issue':{const r=await request(`${W}/works/${state.view.summary.id}/issues`,{expression_id:state.readerVersion,message:$('issue-message').value});$('modal').close();message(`Issue #${r.id} recorded for review.`);break;}
    case 'print':window.print();break;case 'share':await navigator.clipboard.writeText(location.href);message('Workbench link copied.');break;
    case 'expand':if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();break;
  }});});
  render();
})();
